//! 🧪️ Shared region feedback preserves original bytes and independently parsed glyph metrics.
use super::*;
fn region(row: &serde_json::Value) -> ParagraphRegion { ParagraphRegion { width:row["width"].as_f64().unwrap(),height:row["height"].as_f64().unwrap(),origin:[row["origin"][0].as_f64().unwrap(),row["origin"][1].as_f64().unwrap()] } }
#[test]
fn paragraph_regions_reuse_analysis_and_match_original_byte_and_font_sources() {
    let fixture:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();
    let mut unicode_job=UnicodeDataAdmissionJob::new(UNICODE_BYTES.to_vec(),1000000);while!unicode_job.advance(4096,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(4096))).unwrap().done{}let unicode=unicode_job.take_result().unwrap();
    let mut line_job=semio_framework_2d_text_font_shape_unicode::line_break::LineBreakDataAdmissionJob::new(semio_framework_2d_text_font_shape_unicode::line_break::LINE_BREAK_BYTES.to_vec(),1000000);while!line_job.advance(4096,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(4096))).unwrap().done{}let line_data=line_job.take_result().unwrap();
    let mut first=FontFaceAdmissionJob::new(bytes(fixture["font"].as_str().unwrap()),FontOutlineLimits::default());while!first.advance(4096,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(4096))).unwrap().done{}let mut fallback=FontFaceAdmissionJob::new(bytes(fixture["fallback"].as_str().unwrap()),FontOutlineLimits::default());while!fallback.advance(4096,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(4096))).unwrap().done{}let fonts=[first.take_result().unwrap(),fallback.take_result().unwrap()];
    let oracles=[ttf_parser::Face::parse(&fonts[0].source,0).unwrap(),ttf_parser::Face::parse(&fonts[1].source,0).unwrap()];
    let style=ParagraphStyle{width:45.0,origin:[0.0;2],size:fixture["size"].as_f64().unwrap(),line_height:fixture["lineHeight"].as_f64().unwrap(),tracking:0.0,alignment:ParagraphAlignment::Left};
    for case in fixture["cases"].as_array().unwrap(){for grant in[1,7,4096]{
        let text=case["text"].as_str().unwrap();let regions=case["regions"].as_array().unwrap();let mut cursor=FontParagraphCursor::new(text,fonts.len(),style,&[],FontOutlineLimits::default(),unicode.layout,line_data.layout);assert!(cursor.supply_region(ParagraphRegion{width:0.0,height:16.0,origin:[0.0;2]}).is_err());cursor.supply_region(region(&regions[0])).unwrap();
        let mut next=0;let mut pauses=Vec::new();let mut work=0;let mut measure_cycles=0;let mut previous="";
        for _ in 0..1000000{let progress=cursor.advance(text,&fonts,&[],&unicode.source,&line_data.source,grant,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(grant))).unwrap();assert!(progress.work-work<=grant as u64);work=progress.work;if progress.phase=="measure"&&previous!="measure"{measure_cycles+=1;}previous=progress.phase;if progress.phase=="region"{let pause=cursor.flow_pause().unwrap();pauses.push(vec![pause.source_end,pause.line_end,pause.region]);assert!(cursor.result().is_err());assert_eq!(cursor.advance(text,&fonts,&[],&unicode.source,&line_data.source,grant).unwrap().work,work);next+=1;if next<regions.len(){cursor.supply_region(region(&regions[next])).unwrap();}else{cursor.finish_flow().unwrap();}}if progress.done{break;}}
        assert!(measure_cycles<=1);if grant==1{assert_eq!(measure_cycles,1);}let expected:Vec<Vec<usize>>=case["pauses"].as_array().unwrap().iter().map(|row|row.as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize).collect()).collect();assert_eq!(pauses,expected,"{}",case["name"]);
        let output=cursor.take_result().unwrap();let expected=case["lines"].as_array().unwrap();assert_eq!(output.lines.len(),expected.len());let mut glyph_at=0;
        for(at,expected)in expected.iter().enumerate(){let line=output.lines.get(at).unwrap();let placement=cursor.line_placement(at).unwrap();assert_eq!((line.start,line.end),(expected["start"].as_u64().unwrap()as usize,expected["end"].as_u64().unwrap()as usize));assert_eq!(&text[line.start..line.end],expected["text"].as_str().unwrap());assert_eq!(placement.origin,[expected["origin"][0].as_f64().unwrap(),expected["origin"][1].as_f64().unwrap()]);assert_eq!(placement.region,expected["region"].as_u64().unwrap()as usize);let mut x=placement.origin[0];let y=placement.origin[1]+style.size;
            for scalar in expected["text"].as_str().unwrap().chars(){let(face,id)=oracles.iter().enumerate().find_map(|(face,font)|font.glyph_index(scalar).filter(|id|id.0!=0).map(|id|(face,id))).unwrap();let glyph=output.glyphs.get(glyph_at).unwrap();glyph_at+=1;assert_eq!((glyph.face,glyph.glyph),(face,id.0));assert!((glyph.origin[0]-x).abs()<1e-8&&(glyph.origin[1]-y).abs()<1e-8);x+=f64::from(oracles[face].glyph_hor_advance(id).unwrap())*style.size/f64::from(fonts[face].face.units_per_em);}
        }
        assert_eq!(glyph_at,output.glyphs.len());close(cursor);close(output);
    }
    let text=case["text"].as_str().unwrap();let mut cursor=FontParagraphCursor::new(text,fonts.len(),style,&[],FontOutlineLimits::default(),unicode.layout,line_data.layout);cursor.supply_region(region(&case["regions"][0])).unwrap();loop{let progress=cursor.advance(text,&fonts,&[],&unicode.source,&line_data.source,7,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(7))).unwrap();if progress.phase=="region"{cursor.cancel();assert!(cursor.result().is_err());close(cursor);break;}assert!(!progress.done);}
    }
    let [first_font,fallback_font]=fonts;close(first_font);close(fallback_font);close(first);close(fallback);close(line_job);close(line_data);close(unicode_job);close(unicode);
}
